-- rowfence 0.1.0-dev: runtime_fixes. Generated by rowfence migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowfence makes of it changed

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_attribute
             WHERE attrelid = to_regclass('authz.policy_versions') AND attname = 'lock' AND NOT attisdropped) THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock IS DISTINCT FROM '86d07d3b7a532172' THEN
    RAISE EXCEPTION 'rowfence: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      '86d07d3b7a532172', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowfence push or apply since needs the '
                   'migrations from the start (or rowfence apply of the policy the previous migration left)';
  END IF;
END $authz_guard$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowfence''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- The audit trail: entries older than p_keep (no default: how long to keep it is a compliance
-- decision). The trim itself is recorded in the audit trail.
CREATE OR REPLACE FUNCTION authz.trim_audit(p_keep interval) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_before timestamptz; n bigint;
BEGIN
  IF p_keep IS NULL OR p_keep < interval '0' THEN
    RAISE EXCEPTION 'say how long to keep the audit trail, e.g. authz.trim_audit(interval ''2 years'')' USING HINT = 'rowfence help AZ710';
  END IF;
  v_before := now() - p_keep;
  -- the one way past the trigger is DDL, as the owner, here: nothing a session can set lets a DELETE through
  -- (ALTER TABLE takes an exclusive lock on the trail until the transaction ends)
  ALTER TABLE authz.audit DISABLE TRIGGER authz_audit_append_only;
  DELETE FROM authz.audit a WHERE a.at < v_before;
  GET DIAGNOSTICS n = ROW_COUNT;
  ALTER TABLE authz.audit ENABLE TRIGGER authz_audit_append_only;
  INSERT INTO authz.audit (db_role, user_id, action, detail)
  VALUES (authz_int.caller_role(), authz_int.actor(), 'trim_audit',
          jsonb_build_object('before', v_before, 'rows', n));
  RETURN n;
END $f$;

-- The audit trail only grows, except through authz.trim_audit()
CREATE OR REPLACE FUNCTION authz_int.audit_is_append_only() RETURNS trigger
LANGUAGE plpgsql AS $f$
BEGIN
  RAISE EXCEPTION 'the audit trail cannot be changed' USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ711';
END $f$;

-- Everything the user holds a permission on: SELECT * FROM authz.list('folder', 'edit')
-- In pages, in key order: authz.list('file', 'view', NULL, 1000), then the last id seen as p_after
CREATE OR REPLACE FUNCTION authz.list(p_type text, p_perm text, p_after text DEFAULT NULL, p_limit int DEFAULT NULL)
RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  -- a page cursor or size from a request: the caller's mistake, said plainly (the queries below would cast it)
  IF p_limit < 0 THEN
    RAISE EXCEPTION 'the page size must not be negative (got %)', p_limit
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowfence help AZ710';
  END IF;
  IF p_after IS NOT NULL AND NOT coalesce(pg_catalog.pg_input_is_valid(p_after,
                                            (SELECT keytype FROM authz_int.types WHERE name = p_type)), true) THEN
    RAISE EXCEPTION 'the page cursor % is not a % id', quote_literal(left(p_after, 40)), p_type
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowfence help AZ710';
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN; END IF;
  CASE p_type || '.' || p_perm
    WHEN 'user.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."users" o
        WHERE coalesce((id = (SELECT authz.uid())), false);
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."users" o
        WHERE coalesce((id = (SELECT authz.uid())), false)
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."users" o
        WHERE o."id" > p_after::uuid AND coalesce((id = (SELECT authz.uid())), false)
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'bot.manage' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."bots" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."bots" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."bots" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'bot.manage_keys' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."bots" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."bots" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."bots" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'chat.read' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE (EXISTS (SELECT 1 FROM authz_gen."chat__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."chat__bot" v WHERE v.id = o."id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE (EXISTS (SELECT 1 FROM authz_gen."chat__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."chat__bot" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE o."id" > p_after::bigint AND (EXISTS (SELECT 1 FROM authz_gen."chat__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."chat__bot" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'chat.post' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE ((EXISTS (SELECT 1 FROM authz_gen."chat__member" v WHERE v.id = o."id")
    AND NOT coalesce(EXISTS (SELECT 1 FROM authz_gen."chat__blocked" v WHERE v.id = o."id"), false)
    AND (coalesce((not admins_only), false)
    OR EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id")))
    OR EXISTS (SELECT 1 FROM authz_gen."chat__bot" v WHERE v.id = o."id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE ((EXISTS (SELECT 1 FROM authz_gen."chat__member" v WHERE v.id = o."id")
    AND NOT coalesce(EXISTS (SELECT 1 FROM authz_gen."chat__blocked" v WHERE v.id = o."id"), false)
    AND (coalesce((not admins_only), false)
    OR EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id")))
    OR EXISTS (SELECT 1 FROM authz_gen."chat__bot" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE o."id" > p_after::bigint AND ((EXISTS (SELECT 1 FROM authz_gen."chat__member" v WHERE v.id = o."id")
    AND NOT coalesce(EXISTS (SELECT 1 FROM authz_gen."chat__blocked" v WHERE v.id = o."id"), false)
    AND (coalesce((not admins_only), false)
    OR EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id")))
    OR EXISTS (SELECT 1 FROM authz_gen."chat__bot" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'chat.manage' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE o."id" > p_after::bigint AND (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'chat.invite' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE o."id" > p_after::bigint AND (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'chat.join' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__invitee" v WHERE v.id = o."id"))
    OR (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__invitee" v WHERE v.id = o."id"))
    OR (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id")))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE o."id" > p_after::bigint AND ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__invitee" v WHERE v.id = o."id"))
    OR (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id")))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'chat.setup' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = id)), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = id)), false))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = id)), false))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'chat.add_members' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = id)), false))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((kind = 'direct'), false)
    AND coalesce(((select count(*) from ms.members m where m.chat_id = id) < 2), false)));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = id)), false))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((kind = 'direct'), false)
    AND coalesce(((select count(*) from ms.members m where m.chat_id = id) < 2), false)))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE o."id" > p_after::bigint AND ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = o."id"))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = id)), false))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((kind = 'direct'), false)
    AND coalesce(((select count(*) from ms.members m where m.chat_id = id) < 2), false)))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'message.read' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (coalesce((created_at >= coalesce(ms.joined_at(chat_id), '-infinity')), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__read" v WHERE v.id = o."chat_id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (coalesce((created_at >= coalesce(ms.joined_at(chat_id), '-infinity')), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__read" v WHERE v.id = o."chat_id"))
        ORDER BY o."chat_id", o."seq" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (o."chat_id", o."seq") > ((p_after::authz_gen."message__key")."chat_id", (p_after::authz_gen."message__key")."seq") AND (coalesce((created_at >= coalesce(ms.joined_at(chat_id), '-infinity')), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__read" v WHERE v.id = o."chat_id"))
        ORDER BY o."chat_id", o."seq" LIMIT p_limit;
      END IF;
    WHEN 'message.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (coalesce(o."sender_id" = (SELECT authz.uid()), false)
    AND coalesce((not deleted and created_at > now() - interval '15 minutes'), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (coalesce(o."sender_id" = (SELECT authz.uid()), false)
    AND coalesce((not deleted and created_at > now() - interval '15 minutes'), false))
        ORDER BY o."chat_id", o."seq" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (o."chat_id", o."seq") > ((p_after::authz_gen."message__key")."chat_id", (p_after::authz_gen."message__key")."seq") AND (coalesce(o."sender_id" = (SELECT authz.uid()), false)
    AND coalesce((not deleted and created_at > now() - interval '15 minutes'), false))
        ORDER BY o."chat_id", o."seq" LIMIT p_limit;
      END IF;
    WHEN 'message.remove' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (coalesce(o."sender_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."chat__manage" v WHERE v.id = o."chat_id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (coalesce(o."sender_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."chat__manage" v WHERE v.id = o."chat_id"))
        ORDER BY o."chat_id", o."seq" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (o."chat_id", o."seq") > ((p_after::authz_gen."message__key")."chat_id", (p_after::authz_gen."message__key")."seq") AND (coalesce(o."sender_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."chat__manage" v WHERE v.id = o."chat_id"))
        ORDER BY o."chat_id", o."seq" LIMIT p_limit;
      END IF;
    ELSE
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
  END CASE;
END $f$;

-- Share: needs the relation's 'shared by' permission on the object, and every permission
-- the relation grants (you can't grant more than you hold); the subject must exist
CREATE OR REPLACE FUNCTION authz.share(p_type text, p_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text DEFAULT '',
  p_expires_at timestamptz DEFAULT NULL, p_starts_at timestamptz DEFAULT NULL,
  p_caveat text DEFAULT NULL, p_caveat_args jsonb DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_tbl text; v_find text; v_found boolean; v_key text; v_rel authz_int.shared_relations; v_need text;
        v_role authz.roles;
BEGIN
  PERFORM authz_int.check_writable();
  p_id := authz_int.canon(p_type, p_id);
  p_subject_id := authz_int.canon(p_subject_type, p_subject_id);
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
  END IF;
  -- lock the object (FOR KEY SHARE): a concurrent delete waits for us, or we for it
  SELECT t.tbl, t.find INTO v_tbl, v_find FROM authz_int.types t WHERE t.name = p_type;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowfence help AZ707'; END IF;
  IF NOT pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
  END IF;
  EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s x WHERE %s FOR KEY SHARE)', v_tbl, v_find) INTO v_found USING p_id;
  -- a caller who may share nothing on the object gets the answer a missing object gets (this same RAISE),
  -- before the subject and the relation are looked at: sharing never tells a hidden object from a missing one
  v_found := v_found AND EXISTS (
    SELECT 1 FROM (SELECT s.shared_by AS perm FROM authz_int.shared_relations s WHERE s.object_type = p_type
                   UNION SELECT 'share') x
    -- (CASE: authz.can raises for a permission the type doesn't have, and AND doesn't say which runs first)
    WHERE CASE WHEN EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = x.perm)
               THEN authz.can(p_type, p_id, x.perm) ELSE false END);
  IF NOT v_found THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
  END IF;
  v_key := CASE WHEN p_subject_type IN ('anyone', 'link') THEN p_subject_type
                WHEN p_subject_id = '*' AND p_subject_relation = '' THEN p_subject_type || ':*'
                WHEN p_subject_relation <> '' THEN p_subject_type || '#' || p_subject_relation
                ELSE p_subject_type END;
  -- the subject must exist (and is locked, like the object)
  IF v_key NOT LIKE '%:*' AND v_key NOT IN ('anyone', 'link') THEN
    SELECT t.tbl, t.find INTO v_tbl, v_find FROM authz_int.types t WHERE t.name = p_subject_type;
    v_found := v_tbl IS NOT NULL AND pg_catalog.pg_input_is_valid(p_subject_id,
                 (SELECT keytype FROM authz_int.types WHERE name = p_subject_type));
    IF v_found THEN
      EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s x WHERE %s FOR KEY SHARE)', v_tbl, v_find)
        INTO v_found USING p_subject_id;
    END IF;
    IF NOT v_found THEN
      RAISE EXCEPTION 'there is no % %', p_subject_type, p_subject_id USING ERRCODE = 'foreign_key_violation', HINT = 'rowfence help AZ708';
    END IF;
  END IF;
  IF p_relation LIKE 'role:%' THEN
    -- a custom role: its type must match, the subject must be allowed, and you must hold all it grants
    SELECT * INTO v_role FROM authz.roles WHERE 'role:' || id = p_relation;
    IF v_role.id IS NULL OR v_role.object_type <> p_type THEN
      RAISE EXCEPTION 'no role % for %', p_relation, p_type USING HINT = 'rowfence help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.role_subjects WHERE object_type = p_type AND subject = v_key) THEN
      RAISE EXCEPTION 'custom roles on % cannot be given to %', p_type, v_key USING HINT = 'rowfence help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'share')
       OR NOT authz.can(p_type, p_id, 'share') THEN
      RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
    END IF;
    SELECT string_agg(permission, ', ') INTO v_need FROM authz.role_permissions
    WHERE role_id = v_role.id AND NOT authz.can(p_type, p_id, permission);
    IF v_need IS NOT NULL THEN
      RAISE EXCEPTION 'you cannot give role % on % %: you do not hold %', v_role.name, p_type, p_id, v_need
        USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
    END IF;
  ELSE
    SELECT * INTO v_rel FROM authz_int.shared_relations s
    WHERE s.object_type = p_type AND s.relation = p_relation AND s.subject = v_key;
    IF v_rel.relation IS NULL THEN
      RAISE EXCEPTION 'the policy does not allow sharing %.% with %', p_type, p_relation, v_key USING HINT = 'rowfence help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = v_rel.shared_by)
       OR NOT authz.can(p_type, p_id, v_rel.shared_by) THEN
      RAISE EXCEPTION 'you cannot share % % (needs %)', p_type, p_id, v_rel.shared_by USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
    END IF;
    SELECT string_agg(n, ', ') INTO v_need FROM unnest(v_rel.required) n WHERE NOT authz.can(p_type, p_id, n);
    IF v_need IS NOT NULL THEN
      RAISE EXCEPTION 'you cannot grant %.% on % %: you do not hold %', p_type, p_relation, p_type, p_id, v_need
        USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
    END IF;
    IF NOT authz_int.share_if(p_type || '.' || p_relation || '.' || v_key, p_id, p_subject_type,
                              p_subject_id, p_subject_relation) THEN
      RAISE EXCEPTION 'the policy does not allow this share (%)', coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = v_rel.loc), '?') USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ706';
    END IF;
  END IF;
  IF p_caveat IS NOT NULL AND NOT EXISTS (SELECT 1 FROM authz_int.caveats WHERE name = p_caveat) THEN
    RAISE EXCEPTION 'no caveat % in the policy', p_caveat USING HINT = 'rowfence help AZ707';
  END IF;
  INSERT INTO authz.shares (object_type, object_id, relation, subject_type, subject_id, subject_relation,
                            expires_at, created_by, starts_at, caveat, caveat_args)
  VALUES (p_type, p_id, p_relation, p_subject_type, p_subject_id, p_subject_relation,
          p_expires_at, authz_int.actor(), p_starts_at, p_caveat, p_caveat_args)
  ON CONFLICT ON CONSTRAINT shares_pkey
  DO UPDATE SET expires_at = EXCLUDED.expires_at, created_by = EXCLUDED.created_by,
                starts_at = EXCLUDED.starts_at, caveat = EXCLUDED.caveat, caveat_args = EXCLUDED.caveat_args;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."message__read__why"(p_id text, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."message__read");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'message.read = chat.read and {created_at >= coalesce(ms.joined_at(chat_id), ''-infinity'')}';
  BEGIN
    v_ok := (p_id) IN (SELECT ROW(r."chat_id"::bigint, r."seq"::bigint)::text AS id FROM "ms"."messages" r
  WHERE (r."chat_id", r."seq") IN (SELECT (k.k)."chat_id", (k.k)."seq" FROM (SELECT x.id::authz_gen."message__key" AS k FROM (SELECT id FROM authz_int."message__chat__read") x) k)
    AND coalesce((created_at >= coalesce(ms.joined_at(chat_id), '-infinity')), false));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '(chat.read and {created_at >= coalesce(ms.joined_at(chat_id), ''-infinity'')})';
    v_ok := (p_id) IN (SELECT id FROM authz_int."message__chat__read");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'chat.read';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."chat__read" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."chat_id" AS id FROM "ms"."messages" r WHERE (r."chat_id", r."seq") = (((p_id)::authz_gen."message__key")."chat_id", ((p_id)::authz_gen."message__key")."seq") AND r."chat_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the user can't see: nothing about it, or above it
      IF NOT authz_int.visible('chat', v_t.id) THEN
        RETURN NEXT pad || '  ' || '       ' || 'chat is a chat you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'chat is chat '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has read' ELSE ', without read' END;
      IF NOT ('chat:read:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND v_holds) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        RETURN QUERY SELECT * FROM authz_int."chat__read__why"(v_t.id::bigint, p_depth + 2 + 1, p_seen || ('chat:read:' || v_t.id));
      END IF;
    END LOOP;
    v_ok := (p_id) IN (SELECT ROW(r."chat_id"::bigint, r."seq"::bigint)::text AS id FROM "ms"."messages" r WHERE coalesce((created_at >= coalesce(ms.joined_at(chat_id), '-infinity')), false));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '{created_at >= coalesce(ms.joined_at(chat_id), ''-infinity'')}';
  END;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."message__remove__why"(p_id text, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."message__remove");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'message.remove = sender or chat.manage';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."message__sender");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'sender';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."message__sender__why"(p_id, p_depth + 1, p_seen); END IF;
    v_ok := (p_id) IN (SELECT id FROM authz_int."message__chat__manage");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'chat.manage';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."chat__manage" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."chat_id" AS id FROM "ms"."messages" r WHERE (r."chat_id", r."seq") = (((p_id)::authz_gen."message__key")."chat_id", ((p_id)::authz_gen."message__key")."seq") AND r."chat_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the user can't see: nothing about it, or above it
      IF NOT authz_int.visible('chat', v_t.id) THEN
        RETURN NEXT pad || '       ' || 'chat is a chat you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'chat is chat '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has manage' ELSE ', without manage' END;
      IF NOT ('chat:manage:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."chat__manage__why"(v_t.id::bigint, p_depth + 1 + 1, p_seen || ('chat:manage:' || v_t.id));
      END IF;
    END LOOP;
  END;
END $f$;

-- May the signed-in user see this object (select it)? A hidden object reads as a missing one
CREATE FUNCTION authz_int.visible(p_type text, p_id text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF NOT coalesce(pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)), false) THEN
    RETURN false;
  END IF;
  CASE p_type
    WHEN 'user' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."users" "users" WHERE "users"."id" = p_id::uuid
        AND (SELECT authz_int.scope_cmd('ms.users', 'select')) AND coalesce(((SELECT authz.uid()) IS NOT NULL), false));
    WHEN 'bot' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."bots" "bots" WHERE "bots"."id" = p_id::bigint
        AND (SELECT authz_int.scope_cmd('ms.bots', 'select')) AND (coalesce(((SELECT authz.uid()) IS NOT NULL), false)
    AND coalesce((active), false)));
    WHEN 'chat' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."chats" "chats" WHERE "chats"."id" = p_id::bigint
        AND (SELECT authz_int.scope_cmd('ms.chats', 'select')) AND ((EXISTS (SELECT 1 FROM authz_gen."chat__member" v WHERE v.id = "chats"."id")
    OR EXISTS (SELECT 1 FROM authz_gen."chat__bot" v WHERE v.id = "chats"."id"))
    OR ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__invitee" v WHERE v.id = "chats"."id"))
    OR (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__admin" v WHERE v.id = "chats"."id")))
    OR (coalesce("chats"."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = id)), false))));
    WHEN 'membership' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."members" "members" WHERE ("members"."chat_id", "members"."user_id") = (((p_id)::authz_gen."membership__key")."chat_id", ((p_id)::authz_gen."membership__key")."user_id")
        AND (SELECT authz_int.scope_cmd('ms.members', 'select')) AND EXISTS (SELECT 1 FROM authz_gen."chat__read" v WHERE v.id = "members"."chat_id"));
    WHEN 'message' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."messages" "messages" WHERE ("messages"."chat_id", "messages"."seq") = (((p_id)::authz_gen."message__key")."chat_id", ((p_id)::authz_gen."message__key")."seq")
        AND (SELECT authz_int.scope_cmd('ms.messages', 'select')) AND (coalesce((created_at >= coalesce(ms.joined_at(chat_id), '-infinity')), false)
    AND EXISTS (SELECT 1 FROM authz_gen."chat__read" v WHERE v.id = "messages"."chat_id")));
    WHEN 'chat_bot' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."chat_bots" "chat_bots" WHERE ("chat_bots"."chat_id", "chat_bots"."bot_id") = (((p_id)::authz_gen."chat_bot__key")."chat_id", ((p_id)::authz_gen."chat_bot__key")."bot_id")
        AND (SELECT authz_int.scope_cmd('ms.chat_bots', 'select')) AND EXISTS (SELECT 1 FROM authz_gen."chat__read" v WHERE v.id = "chat_bots"."chat_id"));
    WHEN 'block' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."blocks" "blocks" WHERE ("blocks"."blocker_id", "blocks"."blocked_id") = (((p_id)::authz_gen."block__key")."blocker_id", ((p_id)::authz_gen."block__key")."blocked_id")
        AND (SELECT authz_int.scope_cmd('ms.blocks', 'select')) AND coalesce("blocks"."blocker_id" = (SELECT authz.uid()), false));
    ELSE RETURN false;
  END CASE;
END $f$;

-- Why the current user (or, for people who may inspect the object, another user) holds a
-- permission, or what is missing: SELECT * FROM authz.explain('file', 11, 'edit')
CREATE OR REPLACE FUNCTION authz.explain(p_type text, p_id text, p_perm text, p_user text DEFAULT NULL) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_ok boolean; v_bigint bigint; v_text text; v_uuid uuid;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
BEGIN
  -- another user's access: only for people who may inspect the object (the signed-in user may explain their own;
  -- a service whose id is a user's may not)
  IF p_user IS NOT NULL AND authz_int.canon('user', p_user) IS DISTINCT FROM authz.uid()::text
     AND NOT authz_int.may_inspect(p_type, p_id) THEN
    RAISE EXCEPTION 'you cannot inspect access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
  END IF;
  -- people who can't see the object learn nothing about it, whatever else they hold on it (as for a missing one)
  IF p_user IS NULL AND NOT authz_int.may_inspect(p_type, p_id) AND NOT authz_int.visible(p_type, p_id) THEN
    RETURN NEXT 'no   you have no access to ' || p_type || ' ' || p_id;
    RETURN;
  END IF;
  BEGIN
    IF p_user IS NOT NULL THEN
      PERFORM set_config('authz.user_id', p_user, true);
      PERFORM set_config('authz.principal_type', '', true);
      PERFORM authz_int.sign();
    END IF;
    v_ok := authz.can(p_type, p_id, p_perm);
    RETURN NEXT CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || coalesce(coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user') || ' ' || nullif(current_setting('authz.user_id', true), ''), 'nobody')
      || ' ' || CASE WHEN v_ok THEN 'holds ' ELSE 'does not hold ' END || p_perm || ' on ' || p_type || ' ' || p_id;
    CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'edit' THEN RETURN QUERY SELECT * FROM authz_int."user__edit__why"(v_uuid, 1, '{}');
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
      END CASE;
    WHEN 'bot' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'manage' THEN RETURN QUERY SELECT * FROM authz_int."bot__manage__why"(v_bigint, 1, '{}');
        WHEN 'manage_keys' THEN RETURN QUERY SELECT * FROM authz_int."bot__manage_keys__why"(v_bigint, 1, '{}');
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
      END CASE;
    WHEN 'chat' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'read' THEN RETURN QUERY SELECT * FROM authz_int."chat__read__why"(v_bigint, 1, '{}');
        WHEN 'post' THEN RETURN QUERY SELECT * FROM authz_int."chat__post__why"(v_bigint, 1, '{}');
        WHEN 'manage' THEN RETURN QUERY SELECT * FROM authz_int."chat__manage__why"(v_bigint, 1, '{}');
        WHEN 'invite' THEN RETURN QUERY SELECT * FROM authz_int."chat__invite__why"(v_bigint, 1, '{}');
        WHEN 'join' THEN RETURN QUERY SELECT * FROM authz_int."chat__join__why"(v_bigint, 1, '{}');
        WHEN 'setup' THEN RETURN QUERY SELECT * FROM authz_int."chat__setup__why"(v_bigint, 1, '{}');
        WHEN 'add_members' THEN RETURN QUERY SELECT * FROM authz_int."chat__add_members__why"(v_bigint, 1, '{}');
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
      END CASE;
    WHEN 'message' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."message__key"') THEN RETURN; END IF;
      v_text := p_id::authz_gen."message__key"::text;
      CASE p_perm
        WHEN 'read' THEN RETURN QUERY SELECT * FROM authz_int."message__read__why"(v_text, 1, '{}');
        WHEN 'edit' THEN RETURN QUERY SELECT * FROM authz_int."message__edit__why"(v_text, 1, '{}');
        WHEN 'remove' THEN RETURN QUERY SELECT * FROM authz_int."message__remove__why"(v_text, 1, '{}');
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowfence help AZ707';
  END CASE;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('authz.user_id', v_me, true);
    PERFORM set_config('authz.principal_type', v_pt, true);
    PERFORM authz_int.sign();
    RAISE;
  END;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM authz_int.sign();
END $f$;

-- Say who is asking, for this transaction: SELECT authz.act_as('user', '42') (NULL, NULL: nobody), first in each
-- transaction. For the app's backend, which signs people in itself; the session is signed, so nothing but this
-- and the logins can change who is signed in. The app role (and its members) may call it.
CREATE OR REPLACE FUNCTION authz.act_as(p_type text, p_id text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF p_id IS NOT NULL AND coalesce(p_type, 'user') <> 'user'
     AND NOT EXISTS (SELECT 1 FROM authz_int.types WHERE name = p_type AND principal) THEN
    RAISE EXCEPTION '% is not a type that signs in', p_type USING ERRCODE = 'invalid_parameter_value',
      HINT = 'principal types are marked "principal" in the policy: type service = app.services principal (rowfence help AZ707)';
  END IF;
  -- stored as every other id is ('05' is 5), so the audit and created_by name the user as shares do
  PERFORM set_config('authz.user_id', coalesce(authz_int.canon(coalesce(p_type, 'user'), p_id), ''), true);
  PERFORM set_config('authz.principal_type', CASE WHEN p_id IS NULL OR coalesce(p_type, 'user') = 'user' THEN '' ELSE p_type END, true);
  PERFORM set_config('authz.scopes', '', true);
  PERFORM set_config('authz.acting_user', '', true);
  PERFORM authz_int.sign();
END $f$;

-- Sign in with an API key for this transaction: SELECT authz.login_key('ak_...'). Returns who:
-- a user's id, or type:id for another principal
CREATE OR REPLACE FUNCTION authz.login_key(p_token text) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz.api_keys;
BEGIN
  SELECT * INTO k FROM authz.api_keys WHERE hash = encode(sha256(convert_to(coalesce(p_token, ''), 'UTF8')), 'hex');
  IF k.id IS NULL OR k.revoked_at IS NOT NULL OR (k.expires_at IS NOT NULL AND k.expires_at <= now()) THEN
    RAISE EXCEPTION 'invalid API key' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowfence help AZ703';
  END IF;
  PERFORM set_config('authz.user_id', k.user_id, true);
  PERFORM set_config('authz.principal_type', CASE WHEN k.principal_type = 'user' THEN '' ELSE k.principal_type END, true);
  PERFORM set_config('authz.scopes', k.scopes, true);
  PERFORM set_config('authz.acting_user', '', true);
  PERFORM authz_int.sign();
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    PERFORM set_config('authz.user_id', '', true);
    PERFORM set_config('authz.principal_type', '', true);
    RAISE EXCEPTION 'invalid API key' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowfence help AZ703';
  END IF;
  -- when it was last used, to the minute: never waiting on another request with the key (the row they
  -- lock), and not at all in a read-only transaction (a replica, a GET)
  IF pg_catalog.current_setting('transaction_read_only') = 'off' THEN
    UPDATE authz.api_keys SET last_used_at = now()
    WHERE id = (SELECT x.id FROM authz.api_keys x
                WHERE x.id = k.id AND (x.last_used_at IS NULL OR x.last_used_at < now() - interval '1 minute')
                FOR UPDATE SKIP LOCKED);
  END IF;
  RETURN authz_int.actor();
END $f$;

-- Sign in with a JWT (HS256) for this transaction: SELECT authz.login_jwt('eyJ...')
-- Settings (authz.settings): jwt_secret (required), jwt_issuer, jwt_audience, jwt_user_claim (default sub),
-- jwt_type_claim (a claim naming the principal's type, for services; absent or 'user': a user).
-- Tokens must carry exp.
-- A 'scope' claim (space separated) limits the transaction to those policy scopes.
CREATE OR REPLACE FUNCTION authz.login_jwt(p_token text) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE parts text[] := string_to_array(coalesce(p_token, ''), '.'); v_head jsonb; v_claims jsonb; v_secret text;
        v_user text; v_type text; v_scopes text[]; v_now numeric := extract(epoch FROM now()); v_want text;
BEGIN
  SELECT value INTO v_secret FROM authz.settings WHERE key = 'jwt_secret';
  IF v_secret IS NULL THEN RAISE EXCEPTION 'JWT login is not configured (authz.settings jwt_secret)' USING HINT = 'rowfence help AZ703'; END IF;
  BEGIN
    IF cardinality(parts) <> 3 THEN RAISE EXCEPTION 'bad'; END IF;
    v_head := convert_from(authz_int.b64url(parts[1]), 'UTF8')::jsonb;
    v_claims := convert_from(authz_int.b64url(parts[2]), 'UTF8')::jsonb;
    IF v_head->>'alg' IS DISTINCT FROM 'HS256'
       OR authz_int.b64url(parts[3]) <> authz_int.hmac_sha256(convert_to(v_secret, 'UTF8'),
                                                              convert_to(parts[1] || '.' || parts[2], 'UTF8')) THEN
      RAISE EXCEPTION 'bad';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'invalid token' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowfence help AZ703';
  END;
  -- an expiry is required; both are numbers of seconds
  IF jsonb_typeof(v_claims->'exp') IS DISTINCT FROM 'number' OR (v_claims->>'exp')::numeric <= v_now
     OR (v_claims ? 'nbf' AND (jsonb_typeof(v_claims->'nbf') <> 'number' OR (v_claims->>'nbf')::numeric > v_now)) THEN
    RAISE EXCEPTION 'token expired or not yet valid' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowfence help AZ703';
  END IF;
  SELECT value INTO v_want FROM authz.settings WHERE key = 'jwt_issuer';
  IF v_want IS NOT NULL AND v_claims->>'iss' IS DISTINCT FROM v_want THEN
    RAISE EXCEPTION 'token from another issuer' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowfence help AZ703';
  END IF;
  SELECT value INTO v_want FROM authz.settings WHERE key = 'jwt_audience';
  IF v_want IS NOT NULL AND NOT (v_claims->>'aud' = v_want
       OR (jsonb_typeof(v_claims->'aud') = 'array' AND v_claims->'aud' ? v_want)) THEN
    RAISE EXCEPTION 'token for another audience' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowfence help AZ703';
  END IF;
  v_user := v_claims->>coalesce((SELECT value FROM authz.settings WHERE key = 'jwt_user_claim'), 'sub');
  v_type := v_claims->>(SELECT value FROM authz.settings WHERE key = 'jwt_type_claim');
  IF coalesce(v_type, 'user') <> 'user' AND NOT EXISTS (SELECT 1 FROM authz_int.types WHERE name = v_type AND principal) THEN
    RAISE EXCEPTION 'the token names a type that does not sign in' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowfence help AZ703';
  END IF;
  PERFORM set_config('authz.user_id', coalesce(authz_int.canon(coalesce(v_type, 'user'), v_user), ''), true);
  PERFORM set_config('authz.principal_type', CASE WHEN coalesce(v_type, 'user') = 'user' THEN '' ELSE v_type END, true);
  PERFORM set_config('authz.acting_user', '', true);
  IF v_claims ? 'scope' THEN
    v_scopes := ARRAY(SELECT x FROM unnest(string_to_array(v_claims->>'scope', ' ')) x
                      WHERE EXISTS (SELECT 1 FROM authz_int.scope_items WHERE scope = x));
    PERFORM set_config('authz.scopes', CASE WHEN cardinality(v_scopes) = 0 THEN '(none)'
                                            ELSE array_to_string(v_scopes, ',') END, true);
  ELSE
    PERFORM set_config('authz.scopes', '', true);
  END IF;
  PERFORM authz_int.sign();
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    PERFORM set_config('authz.user_id', '', true);
    PERFORM set_config('authz.principal_type', '', true);
    RAISE EXCEPTION 'the token names no active user' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowfence help AZ703';
  END IF;
  RETURN authz_int.actor();
END $f$;

-- Support staff see what a user sees, read-only, for this transaction, with a reason on record:
-- SELECT authz.view_as('42', 'ticket 1234')  (the user type has no impersonate permission: administrators only)
CREATE OR REPLACE FUNCTION authz.view_as(p_user text, p_reason text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := nullif(current_setting('authz.user_id', true), '');
        v_pt text := coalesce(current_setting('authz.principal_type', true), ''); v_actor text := authz_int.actor();
BEGIN
  IF coalesce(current_setting('authz.acting_user', true), '') <> '' THEN
    RAISE EXCEPTION 'already viewing as someone' USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ704';
  END IF;
  IF coalesce(btrim(p_reason), '') = '' THEN
    RAISE EXCEPTION 'say why (the reason is kept in the audit trail)' USING HINT = 'rowfence help AZ710';
  END IF;
  IF NOT (authz_int.caller_is_admin()
          ) THEN
    RAISE EXCEPTION 'you cannot view as user %', p_user USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
  END IF;
  PERFORM set_config('authz.user_id', coalesce(authz_int.canon('user', p_user), ''), true);
  PERFORM set_config('authz.principal_type', '', true);
  PERFORM authz_int.sign();
  IF authz.uid() IS NULL THEN
    PERFORM set_config('authz.user_id', coalesce(v_me, ''), true);
    PERFORM set_config('authz.principal_type', v_pt, true);
    PERFORM authz_int.sign();
    RAISE EXCEPTION 'there is no active user %', p_user USING HINT = 'rowfence help AZ708';
  END IF;
  PERFORM set_config('authz.acting_user', coalesce(v_actor, authz_int.caller_role()), true);
  PERFORM set_config('authz.scopes', 'read', true);
  PERFORM authz_int.sign();
  PERFORM set_config('authz_ctx.reason', p_reason, true);
  PERFORM authz_int.audit('view_as', 'user', authz_int.canon('user', p_user), NULL, NULL, NULL, NULL, NULL);
END $f$;

-- Leaks: SELECT * FROM authz.lint()  (administrators; run after schema changes)
CREATE OR REPLACE FUNCTION authz.lint() RETURNS TABLE (severity text, object text, problem text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r record; v_role oid := to_regrole('ms_app');
BEGIN
  IF v_role IS NULL THEN
    severity := 'error'; object := 'ms_app'; problem := 'the app role does not exist'; RETURN NEXT; RETURN;
  END IF;
  -- the app role itself
  FOR r IN SELECT rolsuper, rolbypassrls FROM pg_roles WHERE oid = v_role AND (rolsuper OR rolbypassrls) LOOP
    severity := 'error'; object := 'ms_app';
    problem := 'is a superuser or has BYPASSRLS: row-level security does not apply to it at all'; RETURN NEXT;
  END LOOP;
  FOR r IN SELECT p.oid::regrole AS parent FROM pg_roles p
           WHERE p.oid <> v_role AND (p.rolsuper OR p.rolbypassrls) AND pg_has_role(v_role, p.oid, 'MEMBER') LOOP
    severity := 'error'; object := 'ms_app';
    problem := format('is a member of %s, which bypasses row-level security', r.parent); RETURN NEXT;
  END LOOP;
  -- rowfence's own objects: nobody but the owner uses them, except for what the policy grants
  FOR r IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = 'ms_app'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = 'ms_app'::regrole AND c.relnamespace = 'authz_gen'::regnamespace AND a.privilege_type = 'SELECT')
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, 'ms_app'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = 'ms_app'::regrole)
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = 'ms_app'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.connection_check()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.unshare(text, bigint, text, text, bigint, text)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.create_role(text, text, text, text, text[])', 'authz.create_role(text, bigint, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.who(text, uuid, text)', 'authz.explain(text, uuid, text, text)', 'authz.list_shares(text, uuid)', 'authz.can(text, bigint, text)', 'authz.can(text, uuid, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.who_among(text, uuid, text, text[], text)', 'authz.perms(text, bigint)', 'authz.perms(text, uuid)']::regprocedure[])) LOOP
    severity := 'error'; object := r.object;
    problem := format('%s holds %s on it, which the policy doesn''t give (a default privilege of the owner, or a grant made since the last apply): the next apply takes it back, or %s', r.who, r.privilege, r.stmt);
    RETURN NEXT;
  END LOOP;
  -- schemas on the search path of the functions that run as the owner, which others may create in
  FOR r IN SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(authz_int.policy_path()) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT nspowner FROM pg_namespace WHERE nspname = 'authz_int'), 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_' LOOP
    severity := 'error'; object := r.schema;
    problem := format('is on the search path of rowfence''s functions that run as the owner, and %s may create in it: a function there can take the place of a built-in one and run as the owner. REVOKE CREATE ON SCHEMA %I FROM %s, or apply with a search path without it', r.who, r.schema, r.who);
    RETURN NEXT;
  END LOOP;
  -- governed tables
  FOR r IN SELECT c.oid::regclass AS tbl, c.relrowsecurity, c.relforcerowsecurity, c.relowner,
                  c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"']::text[]) x) AS governed
           FROM pg_class c WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"']::text[]) x) LOOP
    IF r.relowner = v_role OR pg_has_role(v_role, r.relowner, 'MEMBER') THEN
      IF NOT r.relforcerowsecurity THEN
        severity := 'error'; object := r.tbl::text;
        problem := format('is owned by %s (or a role it belongs to): owners skip row-level security unless you ALTER TABLE %s FORCE ROW LEVEL SECURITY', 'ms_app', r.tbl);
        RETURN NEXT;
      END IF;
    END IF;
    IF NOT r.relrowsecurity AND r.governed THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('row-level security is off, so the policy''s rules don''t apply to it: %s reads and writes every row it has privileges on. Apply the policy again (it turns it on), or ALTER TABLE %s ENABLE ROW LEVEL SECURITY', 'ms_app', r.tbl);
      RETURN NEXT;
    ELSIF NOT r.relrowsecurity AND has_table_privilege(v_role, r.tbl, 'SELECT') THEN
      severity := 'info'; object := r.tbl::text;
      problem := format('%s may read every row (the policy has no rules for this table): fine for a directory, otherwise add rules', 'ms_app');
      RETURN NEXT;
    END IF;
    IF has_table_privilege(v_role, r.tbl, 'TRUNCATE') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may TRUNCATE it, which skips row-level security: REVOKE TRUNCATE ON %s FROM %s', 'ms_app', r.tbl, 'ms_app');
      RETURN NEXT;
    END IF;
  END LOOP;
  -- partitions and inheritance children: used directly, they skip the rules and the triggers of the table above
  -- (apply turns row-level security on for the ones there are then; later ones are found here)
  FOR r IN WITH RECURSIVE d(oid, top, governed) AS (
             SELECT i.inhrelid, i.inhparent, x.governed FROM pg_inherits i
             JOIN (SELECT to_regclass(t) AS tbl, true AS governed FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"']::text[]) t
                   UNION ALL SELECT to_regclass(t), false FROM unnest(ARRAY['"ms"."direct_blocks"']::text[]) t) x
               ON i.inhparent = x.tbl
             UNION SELECT i.inhrelid, d.top, d.governed FROM pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass AS part, d.top::regclass AS tbl, d.governed, k.relrowsecurity
           FROM d JOIN pg_class k ON k.oid = d.oid LOOP
    IF has_table_privilege(v_role, r.part, 'TRUNCATE') THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may TRUNCATE it, which skips row-level security and %s''s triggers: REVOKE TRUNCATE ON %s FROM %s', r.tbl, 'ms_app', r.tbl, r.part, 'ms_app');
      RETURN NEXT;
    END IF;
    IF NOT r.relrowsecurity AND (has_table_privilege(v_role, r.part, 'INSERT') OR has_table_privilege(v_role, r.part, 'UPDATE')
                                 OR has_table_privilege(v_role, r.part, 'DELETE')
                                 OR (r.governed AND has_table_privilege(v_role, r.part, 'SELECT'))) THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may use it directly, without %s''s rules or the triggers that keep inheritance and the audit current: apply the policy again (it turns row-level security on for it), or ALTER TABLE %s ENABLE ROW LEVEL SECURITY', r.tbl, 'ms_app', r.tbl, r.part);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- unique constraints on governed tables tell people that rows they cannot see exist
  FOR r IN SELECT i.indexrelid::regclass AS idx, i.indrelid::regclass AS tbl
           FROM pg_index i WHERE i.indisunique AND NOT i.indisprimary
             AND i.indrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"']::text[]) x)
             AND has_table_privilege(v_role, i.indrelid, 'INSERT') LOOP
    severity := 'info'; object := r.idx::text;
    problem := format('a unique index on %s: inserting a duplicate fails even when the existing row is hidden, which tells the user it exists', r.tbl);
    RETURN NEXT;
  END LOOP;
  -- primary keys the app role may choose (a column it may insert or update, not GENERATED ALWAYS): the same
  FOR r IN SELECT i.indexrelid::regclass AS idx, i.indrelid::regclass AS tbl
           FROM pg_index i WHERE i.indisprimary
             AND i.indrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"']::text[]) x)
             AND EXISTS (SELECT 1 FROM pg_attribute a
                         WHERE a.attrelid = i.indrelid AND a.attnum = ANY (i.indkey) AND a.attidentity <> 'a'
                           AND (has_column_privilege(v_role, i.indrelid, a.attnum, 'INSERT')
                                OR has_column_privilege(v_role, i.indrelid, a.attnum, 'UPDATE'))) LOOP
    severity := 'info'; object := r.idx::text;
    problem := format('the primary key of %s, which %s may choose: an insert with the id of a hidden row fails, which tells the user it exists. Let the database make the ids (GENERATED ALWAYS AS IDENTITY, or random uuids), or revoke INSERT and UPDATE on the key', r.tbl, 'ms_app');
    RETURN NEXT;
  END LOOP;
  -- masked columns must only be readable through their view
  FOR r IN SELECT m.tbl, m.col, m.view FROM authz_int.masked_columns m
           WHERE CASE WHEN EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(m.tbl) AND a.attname = m.col
                                   AND a.attnum > 0 AND NOT a.attisdropped)
                      THEN has_column_privilege(v_role, m.tbl, m.col, 'SELECT') ELSE false END LOOP
    severity := 'error'; object := to_regclass(r.tbl)::text || '.' || r.col;
    problem := format('the policy masks it, but %s may read it from the table (a GRANT to the role, a role it belongs to, or PUBLIC): read it through %s and revoke that', 'ms_app', r.view);
    RETURN NEXT;
  END LOOP;
  -- tables holding relationships (memberships, links) the app role may change directly
  FOR r IN SELECT to_regclass(x) AS tbl FROM unnest(ARRAY['"ms"."direct_blocks"']::text[]) x LOOP
    CONTINUE WHEN r.tbl IS NULL;
    IF has_table_privilege(v_role, r.tbl, 'TRUNCATE') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may TRUNCATE it, which empties memberships without row-level security: REVOKE TRUNCATE ON %s FROM %s', 'ms_app', r.tbl, 'ms_app');
      RETURN NEXT;
    END IF;
    IF (has_table_privilege(v_role, r.tbl, 'INSERT') OR has_table_privilege(v_role, r.tbl, 'UPDATE')
        OR has_table_privilege(v_role, r.tbl, 'DELETE'))
       AND NOT (SELECT relrowsecurity FROM pg_class WHERE oid = r.tbl) THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may change it, and it decides who is in what: anyone could add themselves. Revoke the write privileges, or give it rules', 'ms_app');
      RETURN NEXT;
    END IF;
  END LOOP;
  -- columns that grant a relation, changed by anyone who may update the row
  FOR r IN SELECT * FROM (VALUES (NULL::text, NULL::text, NULL::text, NULL::text)) v(tbl, col, what, loc)
           WHERE tbl IS NOT NULL LOOP
    IF EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(r.tbl) AND a.attname = r.col
               AND a.attnum > 0 AND NOT a.attisdropped)
       AND has_column_privilege(v_role, r.tbl, r.col, 'UPDATE') THEN
      severity := 'warning'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('grants %s (%s), and anyone who may update the row may change it: add a rule such as "update %s : share"', r.what, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.col);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- JIT for the app role: checks are many small subplans, which JIT may spend longer compiling than running
  IF coalesce((SELECT split_part(c, '=', 2) FROM pg_db_role_setting s, unnest(s.setconfig) c
               WHERE s.setrole = v_role AND c LIKE 'jit=%'
                 AND s.setdatabase IN (0, (SELECT d.oid FROM pg_database d WHERE d.datname = current_database()))
               ORDER BY s.setdatabase DESC LIMIT 1), current_setting('jit')) IN ('on', 'true', '1') THEN
    severity := 'info'; object := 'ms_app';
    problem := format('runs with JIT on: permission checks are many small subplans, and JIT can take longer to compile a read than to run it (hundreds of ms): ALTER ROLE %s SET jit = off', 'ms_app');
    RETURN NEXT;
  END IF;
  -- relations named like a type
  FOR r IN SELECT * FROM (VALUES ('chat', 'bot', 'relation chat.bot'), ('membership', 'chat', 'relation membership.chat'), ('message', 'chat', 'relation message.chat'), ('chat_bot', 'chat', 'relation chat_bot.chat'), ('chat_bot', 'bot', 'relation chat_bot.bot')) v(type, rel, loc)
           WHERE type IS NOT NULL LOOP
    severity := 'info'; object := r.type || '.' || r.rel;
    problem := format('is named like the type %s (%s), so in rules it reads like the type: a name that says what the relation is (author, member) reads better', r.rel, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'));
    RETURN NEXT;
  END LOOP;
  -- columns that move a row under another, with nothing checking where it moves to
  FOR r IN SELECT * FROM (VALUES (NULL::text, NULL::text, NULL::text, NULL::text)) v(tbl, col, rel, loc)
           WHERE tbl IS NOT NULL LOOP
    IF has_column_privilege(v_role, r.tbl, r.col, 'UPDATE') THEN
      severity := 'warning'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('moves a row under another (%s, %s), and nothing checks where it moves to, so anyone who may update a row may put it inside something they may not change: add a rule such as "update %s after : %s.edit"', r.rel, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.col, r.rel);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- views over governed tables that run with their owner's rights
  FOR r IN SELECT DISTINCT v.oid::regclass AS view, d.refobjid::regclass AS tbl
           FROM pg_depend d JOIN pg_rewrite w ON w.oid = d.objid JOIN pg_class v ON v.oid = w.ev_class
           LEFT JOIN pg_description ds ON ds.objoid = v.oid AND ds.classoid = 'pg_class'::regclass
           WHERE d.classid = 'pg_rewrite'::regclass AND d.refclassid = 'pg_class'::regclass
             AND d.refobjid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"', '"ms"."blocks"', '"ms"."chat_bots"', '"ms"."direct_blocks"', '"ms"."members"']::text[]) x)
             AND v.oid <> d.refobjid AND v.relkind IN ('v', 'm')
             AND v.relnamespace NOT IN (to_regnamespace('authz_gen'), to_regnamespace('authz_int'))
             AND coalesce(ds.description, '') <> 'authzc masked view'
             AND NOT coalesce(v.reloptions @> ARRAY['security_invoker=true'], false)
             AND NOT coalesce(v.reloptions @> ARRAY['security_invoker=on'], false)
             AND has_table_privilege(v_role, v.oid, 'SELECT') LOOP
    severity := 'error'; object := r.view::text;
    problem := format('%s may read this view of %s, and views run with their owner''s rights, so row-level security does not apply: ALTER VIEW %s SET (security_invoker = on)', 'ms_app', r.tbl, r.view);
    RETURN NEXT;
  END LOOP;
  -- functions that read governed tables as their owner
  FOR r IN SELECT p.oid::regprocedure AS fn FROM pg_proc p
           WHERE p.prosecdef AND p.pronamespace NOT IN (to_regnamespace('authz'), to_regnamespace('authz_int'),
                                                       to_regnamespace('authz_gen'), 'pg_catalog'::regnamespace)
             AND has_function_privilege(v_role, p.oid, 'EXECUTE')
             AND p.prokind IN ('f', 'p')
             AND EXISTS (SELECT 1 FROM unnest(ARRAY['ms.blocks', 'ms.bots', 'ms.chat_bots', 'ms.chats', 'ms.members', 'ms.messages', 'ms.users', 'ms.blocks', 'ms.chat_bots', 'ms.direct_blocks', 'ms.members']::text[]) x
                         WHERE lower(replace(pg_get_functiondef(p.oid), '"', '')) ~
                               ('(from|join|update|into|table|only)\s+(' || lower(split_part(x, '.', 1)) || '\.)?'
                                || lower(split_part(x, '.', 2)) || '([^a-z0-9_$]|$)')) LOOP
    severity := 'warning'; object := r.fn::text;
    problem := 'SECURITY DEFINER, callable by the app role, and seems to use a governed table: it reads rows without row-level security unless its owner is subject to it';
    RETURN NEXT;
  END LOOP;
  -- lookups the permission views make
  FOR r IN SELECT * FROM (VALUES ('"ms"."blocks"', 'blocker_id', 'user.has_blocked: find the members of an object; block.blocker: find objects by blocker_id'), ('"ms"."blocks"', 'blocked_id', 'user.has_blocked: find what a subject is in'), ('"ms"."bots"', 'owner_id', 'bot.owner: find objects by owner_id'), ('"ms"."members"', 'chat_id', 'chat.member: find the members of an object; chat.admin: find the members of an object; chat.owner: find the members of an object; membership.chat: find objects by chat_id'), ('"ms"."members"', 'user_id', 'chat.member: find what a subject is in; chat.admin: find what a subject is in; chat.owner: find what a subject is in; membership.person: find objects by user_id'), ('"ms"."chats"', 'created_by', 'chat.creator: find objects by created_by'), ('"ms"."chat_bots"', 'chat_id', 'chat.bot: find the members of an object; chat_bot.chat: find objects by chat_id'), ('"ms"."chat_bots"', 'bot_id', 'chat.bot: find what a subject is in; chat_bot.bot: find objects by bot_id'), ('"ms"."direct_blocks"', 'chat_id', 'chat.blocked: find the members of an object'), ('"ms"."direct_blocks"', 'user_id', 'chat.blocked: find what a subject is in'), ('"ms"."messages"', 'chat_id', 'message.chat: find objects by chat_id'), ('"ms"."messages"', 'sender_id', 'message.sender: find objects by sender_id'), ('"ms"."messages"', 'bot_id', 'message.from_bot: find objects by bot_id')) v(tbl, col, why) WHERE tbl IS NOT NULL LOOP
    CONTINUE WHEN to_regclass(r.tbl) IS NULL;
    -- a plain view can't have an index: the tables under it answer the lookups
    CONTINUE WHEN (SELECT c.relkind FROM pg_class c WHERE c.oid = to_regclass(r.tbl)) = 'v';
    -- an index whose first columns are these (one, or a composite key's, in any order)
    IF NOT EXISTS (SELECT 1 FROM pg_index i
                   WHERE i.indrelid = to_regclass(r.tbl)
                     AND (SELECT array_agg(a.attname::text ORDER BY a.attname)
                          FROM unnest((i.indkey::int2[])[0:cardinality(string_to_array(r.col, ', ')) - 1]) k
                          JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k)
                         = (SELECT array_agg(c ORDER BY c) FROM unnest(string_to_array(r.col, ', ')) c)) THEN
      severity := 'performance'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('no index starts with %s (%s): CREATE INDEX ON %s (%s)',
                        CASE WHEN r.col LIKE '%, %' THEN 'these columns' ELSE 'this column' END, r.why, to_regclass(r.tbl),
                        (SELECT string_agg(quote_ident(c), ', ') FROM unnest(string_to_array(r.col, ', ')) c));
      RETURN NEXT;
    END IF;
  END LOOP;
  -- JIT compiles big RLS reads (a list of many rows) for ~0.5 s each time
  IF current_setting('jit') = 'on' AND NOT EXISTS (
       SELECT 1 FROM pg_db_role_setting s, unnest(s.setconfig) c
       WHERE s.setrole = v_role AND c IN ('jit=off', 'jit=false', 'jit=0')) THEN
    severity := 'performance'; object := 'ms_app';
    problem := format('JIT is on: reads that scan many rows through row-level security can spend about half a second compiling. ALTER ROLE %s SET jit = off', 'ms_app');
    RETURN NEXT;
  END IF;
END $f$;

-- What is wrong with this connection, for the app to check when it starts: SELECT * FROM authz.connection_check()
-- 'error': the rules don't apply to the role this connection runs as; 'performance'; 'info'. No rows: all is well.
CREATE OR REPLACE FUNCTION authz.connection_check() RETURNS TABLE (severity text, problem text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me oid := to_regrole(authz_int.caller_role()); v_app oid := to_regrole('ms_app'); r record;
BEGIN
  IF (SELECT rolsuper FROM pg_roles WHERE oid = v_me) THEN
    severity := 'error'; problem := format('%s is a superuser: row-level security does not apply to it', v_me::regrole);
    RETURN NEXT; RETURN;
  END IF;
  IF (SELECT rolbypassrls FROM pg_roles WHERE oid = v_me) THEN
    severity := 'error'; problem := format('%s has BYPASSRLS: row-level security does not apply to it', v_me::regrole);
    RETURN NEXT;
  END IF;
  -- a table's owner (or a role with its rights) skips row-level security, unless the table forces it
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"']::text[]) x)
             AND NOT c.relforcerowsecurity AND pg_has_role(v_me, c.relowner, 'USAGE') LOOP
    severity := 'error';
    problem := format('%s owns %s (or has its owner''s rights): owners skip row-level security', v_me::regrole, r.tbl);
    RETURN NEXT;
  END LOOP;
  -- a table with rules whose row-level security is off: the rules don't apply
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"']::text[]) x) AND NOT c.relrowsecurity LOOP
    severity := 'error';
    problem := format('row-level security is off on %s: the policy''s rules don''t apply to it', r.tbl);
    RETURN NEXT;
  END LOOP;
  -- a login that switched to the app role (SET ROLE) but is an administrator: RESET ROLE leaves row-level
  -- security, and its sessions are believed without a signature
  FOR r IN SELECT l.oid::regrole AS login FROM pg_roles l, pg_namespace n
           WHERE l.rolname = session_user AND n.nspname = 'authz_int' AND l.oid <> v_me
             AND (l.rolsuper OR l.rolbypassrls OR pg_has_role(l.oid, n.nspowner, 'MEMBER')) LOOP
    severity := 'error';
    problem := format('this connection logs in as %s, a superuser, BYPASSRLS or the policy''s owner, and switched to %s: RESET ROLE leaves row-level security, and who is signed in is believed without a signature. Log in as the app role', r.login, v_me::regrole);
    RETURN NEXT;
  END LOOP;
  IF v_app IS NULL OR NOT pg_has_role(v_me, v_app, 'USAGE') THEN
    severity := 'error';
    problem := format('%s is not the policy''s app role %s, nor a member of it: the rules apply to %s only',
                      v_me::regrole, 'ms_app', 'ms_app');
    RETURN NEXT;
  END IF;
  IF current_setting('jit') = 'on' THEN
    severity := 'performance';
    problem := 'JIT is on: reads through row-level security can spend more time compiling than running (ALTER ROLE ... SET jit = off)';
    RETURN NEXT;
  END IF;
END $f$;

-- Privileges the policy doesn't give on rowfence's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = 'ms_app'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = 'ms_app'::regrole AND c.relnamespace = 'authz_gen'::regnamespace AND a.privilege_type = 'SELECT')
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, 'ms_app'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = 'ms_app'::regrole)
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = 'ms_app'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.connection_check()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.unshare(text, bigint, text, text, bigint, text)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.create_role(text, text, text, text, text[])', 'authz.create_role(text, bigint, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.who(text, uuid, text)', 'authz.explain(text, uuid, text, text)', 'authz.list_shares(text, uuid)', 'authz.can(text, bigint, text)', 'authz.can(text, uuid, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.who_among(text, uuid, text, text[], text)', 'authz.perms(text, bigint)', 'authz.perms(text, uuid)']::regprocedure[])) LOOP
    EXECUTE g.stmt;
    v_taken := v_taken + 1;
  END LOOP;
  IF v_taken > 0 THEN
    RAISE WARNING 'took back % privileges on rowfence''s schemas that the policy doesn''t give (default privileges of the owner, or grants made since the last apply)', v_taken;
  END IF;
END $r$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz FROM PUBLIC;

GRANT USAGE ON SCHEMA authz, authz_gen TO ms_app;

GRANT SELECT ON ALL TABLES IN SCHEMA authz_gen TO ms_app;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz_gen FROM PUBLIC;

GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA authz_gen TO ms_app;

GRANT EXECUTE ON FUNCTION
  authz.uid(),
  authz.principal(),
  authz.ctx(text),
  authz.link_hashes(),
  authz.act_as(text, text),
  authz.connection_check(),
  authz.can(text, text, text),
  authz.list(text, text, text, integer),
  authz.perms(text, text),
  authz.perms_of(text, text[]),
  authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb),
  authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb),
  authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb),
  authz.unshare(text, text, text, text, text, text),
  authz.unshare(text, bigint, text, text, bigint, text),
  authz.unshare(text, bigint, text, text, text, text),
  authz.create_link(text, text, text, timestamptz),
  authz.create_link(text, bigint, text, timestamptz),
  authz.create_role(text, text, text, text, text[]),
  authz.create_role(text, bigint, text, text, text[]),
  authz.set_role_permissions(bigint, text[]),
  authz.delete_role(bigint),
  authz.roles_of(text, text),
  authz.who(text, text, text),
  authz.explain(text, text, text, text),
  authz.list_shares(text, text),
  authz.explain_rule(text, text, text, jsonb),
  authz.who_among(text, text, text, text[], text),
  authz.create_api_key(text, text, timestamptz, text, text),
  authz.list_api_keys(text, text),
  authz.revoke_api_key(bigint),
  authz.login_key(text),
  authz.login_jwt(text),
  authz.view_as(text, text),
  authz.request_access(text, text, text, text, interval),
  authz.request_access(text, bigint, text, text, interval),
  authz.pending_requests(),
  authz.decide_request(bigint, boolean, text),
  authz.cancel_request(bigint),
  authz.break_glass(text, text, text, text, interval),
  authz.start_review(text, text, timestamptz),
  authz.review_items(bigint),
  authz.review_decide(bigint, integer, boolean),
  authz.close_review(bigint, boolean),
  authz.who(text, bigint, text),
  authz.explain(text, bigint, text, text),
  authz.list_shares(text, bigint),
  authz.who(text, uuid, text),
  authz.explain(text, uuid, text, text),
  authz.list_shares(text, uuid),
  authz.can(text, bigint, text),
  authz.can(text, uuid, text),
  authz.who_among(text, bigint, text, text[], text),
  authz.who_among(text, uuid, text, text[], text),
  authz.perms(text, bigint),
  authz.perms(text, uuid)
  TO ms_app;

-- the policy now in force
INSERT INTO authz.policy_versions (action, policy, files, version, lock)
VALUES ('apply', $authz_policy$-- policy.authz: every access rule of the messenger. Applied by db/migrate.py with authz.apply(); the
-- backend has no permission checks of its own. Read it top to bottom: people, bots, chats, then what
-- each table allows.

role ms_app

type user = ms.users (id uuid)
  has_blocked : user = ms.blocks(blocker_id -> blocked_id)  -- the people this person blocked
  can edit = {id = authz.uid()}                             -- your own profile

-- bots are services: they sign in with their own API keys (made by their owner) and post as themselves
type bot = ms.bots principal where {active}
  owner : user = owner_id
  can manage      = owner
  can manage_keys = owner

type chat = ms.chats
  member  : user = ms.members(chat_id -> user_id)
  admin   : user = ms.members(chat_id -> user_id) where {role in ('admin', 'owner')}
  owner   : user = ms.members(chat_id -> user_id) where {role = 'owner'}
  creator : user = created_by
  bot     : bot  = ms.chat_bots(chat_id -> bot_id)
  blocked : user = ms.direct_blocks(chat_id -> user_id)     -- a direct chat where one blocked the other
  invitee : link  shared by invite                          -- invite links: anyone holding one

  can read   = member or bot
  -- members post, unless blocked in a direct chat, or the group is for announcements and they aren't an admin
  can post   = (member and not blocked and ({not admins_only} or admin)) or bot
  can manage = admin and {kind = 'group'}                  -- the title, the members, bots, invite links
  can invite = manage
  can join   = (invitee and {kind = 'group'}) or manage     -- (admins may make links, so they hold what links give)
  -- a chat just created, before anyone is in it: its creator sees it and adds themselves
  can setup  = creator and {not exists (select 1 from ms.members m where m.chat_id = id)}
  -- adding people: admins of a group; the one who starts a direct chat adds the other person
  can add_members = manage or setup
                 or (creator and {kind = 'direct'} and {(select count(*) from ms.members m where m.chat_id = id) < 2})

-- a membership row: a person in a chat. Its key is (chat_id, user_id)
type membership = ms.members (chat_id, user_id uuid)
  chat   : chat = chat_id
  person : user = user_id

-- messages are numbered per chat; you read what was said since you joined
type message = ms.messages (chat_id, seq)
  chat     : chat = chat_id
  sender   : user = sender_id
  from_bot : bot  = bot_id

  can read   = chat.read and {created_at >= coalesce(ms.joined_at(chat_id), '-infinity')}
  can edit   = sender and {not deleted and created_at > now() - interval '15 minutes'}
  can remove = sender or chat.manage                       -- delete for everyone

type chat_bot = ms.chat_bots (chat_id, bot_id)
  chat : chat = chat_id
  bot  : bot  = bot_id

type block = ms.blocks (blocker_id uuid, blocked_id uuid)
  blocker : user = blocker_id

rules ms.users
  select                       : signed_in                  -- to find people by phone number
  update                       : edit
  update id, phone, created_at : {false}

rules ms.bots
  select            : signed_in
  insert            : {owner_id = authz.uid()}
  update            : manage
  update id, owner_id : {false}
  delete            : manage

rules ms.chats
  select                                 : read or join or setup
  insert                                 : signed_in and {created_by = authz.uid()}
  update                                 : manage
  update kind, created_by, created_at, last_seq : {false}
  delete                                 : owner and {kind = 'group'}

rules ms.members
  -- added by someone who may (not as an admin unless they are one), never someone who blocked you;
  -- or yourself, with an invite link
  insert                          : (chat.add_members and ({role = 'member'} or chat.manage or chat.setup)
                                     and not person.has_blocked)
                                    or (chat.join and person and {role = 'member'})
  select                          : chat.read
  update                          : chat.manage or person
  update role                     : chat.manage and {role <> 'owner'}       -- nobody demotes the owner
  update role after               : {role <> 'owner'}                        -- nor makes another
  update last_read_seq            : person
  update chat_id, user_id, joined_at : {false}
  delete                          : person or (chat.manage and {role <> 'owner'})   -- leave, or be removed

rules ms.messages
  select                          : read
  insert                          : chat.post and ((sender and {bot_id is null}) or (from_bot and {sender_id is null}))
  update                          : edit or remove
  update body after               : (edit and {not deleted}) or {deleted and body = ''}
  update deleted                  : remove
  update deleted after            : {deleted}                                -- no undelete
  update chat_id, seq, sender_id, bot_id, created_at : {false}
  delete                          : {false}                                  -- messages are deleted for everyone, not removed

rules ms.chat_bots
  select : chat.read
  insert : chat.manage and bot.manage and {added_by = authz.uid()}          -- your own bots, into chats you manage
  delete : chat.manage or bot.manage

rules ms.blocks
  select : blocker
  insert : blocker
  delete : blocker
$authz_policy$,
  $authz_files${}$authz_files$::jsonb, '0.1.0-dev+f6bb86ca3415', '472bbc0113b10f57');
